from typing import List

class Solution:
    def canJump(self, nums: List[int]) -> bool:
        n = len(nums)

        def dfs(i: int) -> bool:
            # Once we reach or cross the last index, the game is won.
            if i >= n - 1:
                return True
            for step in range(1, nums[i] + 1):
                if dfs(i + step):
                    return True
            return False

        return dfs(0)

