from functools import lru_cache
from typing import List

class Solution:
    def canJump(self, nums: List[int]) -> bool:
        n = len(nums)

        @lru_cache(None)
        def good(i: int) -> bool:
            if i >= n - 1:
                return True
            furthest = min(n - 1, i + nums[i])
            for nxt in range(i + 1, furthest + 1):
                if good(nxt):
                    return True
            return False

        return good(0)

